package org.solarelevation.alarm;
import android.app.*;
import android.content.*;
import android.net.*;
import android.os.*;
import java.io.*;
import java.math.*;
public final class SolarAlarmSchedule {
public static final String SOURCE_ID="SolarAlarmSchedule_v20261022T031609Z";
public static final String EXTRA_ID="event_id",EXTRA_GEN="generation",EXTRA_WHEN="utc_ms";
private static PendingIntent alarm(Context c,long id,long gen,long time){Intent i=new Intent(c,SolarAlarmReceiver.class);i.setAction("org.solarelevation.alarm.FIRE");i.setData(Uri.parse("solar-alarm://event/"+id));i.putExtra(EXTRA_ID,id);i.putExtra(EXTRA_GEN,gen);i.putExtra(EXTRA_WHEN,time);return PendingIntent.getBroadcast(c,(int)id,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
public static boolean capability(Context c){AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);return Build.VERSION.SDK_INT<31||am.canScheduleExactAlarms();}
public static void cancel(Context c,long id){AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);am.cancel(alarm(c,id,0,0));}
private static void enqueue(Context c,SolarAlarmStore.Event e){AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);PendingIntent show=PendingIntent.getActivity(c,(int)e.id,new Intent(c,SolarAlarmMainActivity.class).setAction("org.solarelevation.alarm.OPEN."+e.id),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);am.setAlarmClock(new AlarmManager.AlarmClockInfo(e.next,show),alarm(c,e.id,e.gen,e.next));}
public static synchronized String setEnabled(Context context,long id,boolean enabled){Context c=context.getApplicationContext();SolarAlarmStore db=new SolarAlarmStore(c);if(db.get(id)==null){db.close();return "Event missing";}db.setEnabled(id,enabled);cancel(c,id);db.close();return enabled?arm(c,id):"Disabled";}
public static synchronized String arm(Context context,long id){Context c=context.getApplicationContext();SolarAlarmStore db=new SolarAlarmStore(c);SolarAlarmStore.Event e=db.get(id);if(e==null){db.close();return "Event missing";}if(e.enabled==0){cancel(c,id);db.setSchedule(id,0,"Disabled");db.close();return "Disabled";}String state;long next=0;int resolvedDirection=e.direction==-1?-1:1;try{if(e.uri.isEmpty())throw new IOException("Choose an audio file");SolarAlarmAudio.validate(c,e.uri,e.file);if(!SolarAlarmEphemeris.ready(c))throw new IOException("Download JPL DE440s first");SolarAlarmEphemeris.verify(c);if(!capability(c))throw new IOException("Exact-alarm authorization missing");android.content.SharedPreferences pos=c.getSharedPreferences("position",0);if(!pos.contains("lat"))throw new IOException("No GPS or last-known position");double angle=new BigDecimal(e.angle).doubleValue();if(!Double.isFinite(angle)||angle<-90||angle>90)throw new IOException("Invalid solar elevation");try(SolarAlarmEphemeris eph=new SolarAlarmEphemeris(SolarAlarmEphemeris.path(c))){next=SolarAlarmSolar.next(eph,System.currentTimeMillis(),Double.longBitsToDouble(pos.getLong("lat",0)),Double.longBitsToDouble(pos.getLong("lon",0)),Double.longBitsToDouble(pos.getLong("height",0)),angle,e.direction);if(next>0&&e.direction==0){double before=SolarAlarmSolar.altitude(eph,next-60000L,Double.longBitsToDouble(pos.getLong("lat",0)),Double.longBitsToDouble(pos.getLong("lon",0)),Double.longBitsToDouble(pos.getLong("height",0)));double after=SolarAlarmSolar.altitude(eph,next+60000L,Double.longBitsToDouble(pos.getLong("lat",0)),Double.longBitsToDouble(pos.getLong("lon",0)),Double.longBitsToDouble(pos.getLong("height",0)));resolvedDirection=after>=before?1:-1;}}if(next<0)throw new IOException("No crossing within 370-day horizon");state="Armed";}catch(InterruptedIOException ex){db.close();return "Recalculation interrupted; prior schedule retained";}catch(Exception ex){if(Thread.currentThread().isInterrupted()){db.close();return "Recalculation interrupted; prior schedule retained";}state="Blocked: "+ex.getMessage();next=0;}SolarAlarmStore.Event latest=db.get(id);if(latest==null||latest.gen!=e.gen||latest.enabled!=1){db.close();return "Schedule changed while recalculating";}cancel(c,id);long gen=db.setSchedule(id,next,state,resolvedDirection);if(next>0&&gen>0){SolarAlarmStore.Event now=db.get(id);try{enqueue(c,now);}catch(Exception ex){state="Blocked: Android refused exact alarm: "+ex.getMessage();db.setSchedule(id,0,state);}}db.close();return state;}
public static void restore(Context c){SolarAlarmStore db=new SolarAlarmStore(c);for(SolarAlarmStore.Event e:db.all()){if(e.enabled==0)continue;try{if(e.next>System.currentTimeMillis()+5000&&e.status.equals("Armed")&&capability(c))enqueue(c,e);else arm(c,e.id);}catch(Exception ignored){db.status(e.id,"Blocked: rescheduling failed");}}db.close();}
private SolarAlarmSchedule(){}
}
